instrument SESANS_Example {
    // Instrument parameters
    real L0 = 2.165; // [m] Center wavelength
    real DL = 0.02;  // [m] Wavelength spread
    real By = 0.00468; // [T] Magnetic field in y-direction

    // Source parameters
    real src_yheight = 0.01; // [m]
    real src_xwidth = 0.01; // [m]
    real src_dist = 2.25; // [m]
    real src_focus_xw = 0.01; // [m]
    real src_focus_yh = 0.01; // [m]
    real src_lambda0 = L0; // [m]
    real src_dlambda = DL; // [m]
    int src_gauss = 1;

    // Set_pol parameters
    real set_pol_px = 1;

    // PolLambda_monitor parameters
    int px_nL = 501;
    int px_restore_neutron = 1;
    string px_filename = "pxAfterAnalyser";
    int px_mx = 1;
    real px_Lmin = L0 - DL;
    real px_Lmax = L0 + DL;

    // Foil_flipper_magnet parameters
    real f_xwidth = 0.1; // [m]
    real f_yheight = 0.1; // [m]
    real f_zdepth = 0.3; // [m]
    real f_phi = 0.095993; // [rad]
    real f_foilthick = 3.0; // [m]
    real f_Bx = 0; // [T]
    real f_By = By; // [T]
    real f_Bz = 0; // [T]
    int f_foil_in = 1;
    int f_verbose = 0;

    // SANS_spheres2 parameters
    real sans_xwidth = 0.02; // [m]
    real sans_yheight = 0.02; // [m]
    real sans_zthick = 0.001; // [m]
    real sans_dsdw_inc = 0.0;
    real sans_sc_aim = 0.8;
    real sans_sans_aim = 0.95;
    real sans_R = 10000; // [m]
    real sans_phi = 0.015; // [rad]
    int sans_singlesp = 0;
    real sans_Qmind = 0.00003; // [1/m]
    real sans_Qmaxd = 0.001; // [1/m]

    // PSD_monitor parameters
    int det_nx = 101;
    int det_ny = 101;
    string det_filename = "det";
    real det_xwidth = 0.011; // [m]
    real det_yheight = 0.011; // [m]

    // Define components in beam order
    Progress_bar origin AT (0, 0, 0) RELATIVE ABSOLUTE ROTATED (0, 0, 0) RELATIVE ABSOLUTE;

    Source_simple src AT (0, 0, 0) RELATIVE origin ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        yheight = src_yheight,
        xwidth = src_xwidth,
        dist = src_dist,
        focus_xw = src_focus_xw,
        focus_yh = src_focus_yh,
        lambda0 = src_lambda0,
        dlambda = src_dlambda,
        gauss = src_gauss;

    Set_pol set_pol AT (0, 0, 0.1) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        px = set_pol_px;

    PolLambda_monitor px1 AT (0, 0, 0.01) RELATIVE set_pol ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        nL = px_nL,
        restore_neutron = px_restore_neutron,
        filename = px_filename,
        mx = px_mx,
        Lmin = px_Lmin,
        Lmax = px_Lmax;

    Foil_flipper_magnet f1 AT (0, 0, 0.5) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        xwidth = f_xwidth,
        yheight = f_yheight,
        zdepth = f_zdepth,
        phi = f_phi,
        foilthick = f_foilthick,
        Bx = f_Bx,
        By = f_By,
        Bz = f_Bz,
        foil_in = f_foil_in,
        verbose = f_verbose;

    PolLambda_monitor px2 AT (0, 0, 0.16) RELATIVE f1 ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        nL = px_nL,
        restore_neutron = px_restore_neutron,
        filename = px_filename,
        mx = px_mx,
        Lmin = px_Lmin,
        Lmax = px_Lmax;

    Foil_flipper_magnet f2 AT (0, 0, 2.0) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        xwidth = f_xwidth,
        yheight = f_yheight,
        zdepth = f_zdepth,
        phi = f_phi,
        foilthick = f_foilthick,
        Bx = f_Bx,
        By = f_By,
        Bz = f_Bz,
        foil_in = f_foil_in,
        verbose = f_verbose;

    PolLambda_monitor px3 AT (0, 0, 0.16) RELATIVE f2 ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        nL = px_nL,
        restore_neutron = px_restore_neutron,
        filename = px_filename,
        mx = px_mx,
        Lmin = px_Lmin,
        Lmax = px_Lmax;

    SANS_spheres2 sans_spheres AT (0, 0, 2.25) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        xwidth = sans_xwidth,
        yheight = sans_yheight,
        zthick = sans_zthick,
        dsdw_inc = sans_dsdw_inc,
        sc_aim = sans_sc_aim,
        sans_aim = sans_sans_aim,
        R = sans_R,
        phi = sans_phi,
        singlesp = sans_singlesp,
        Qmind = sans_Qmind,
        Qmaxd = sans_Qmaxd;

    Foil_flipper_magnet f3 AT (0, 0, 2.5) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        xwidth = f_xwidth,
        yheight = f_yheight,
        zdepth = f_zdepth,
        phi = f_phi,
        foilthick = f_foilthick,
        Bx = f_Bx,
        By = f_By,
        Bz = f_Bz,
        foil_in = f_foil_in,
        verbose = f_verbose;

    Foil_flipper_magnet f4 AT (0, 0, 4.0) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        xwidth = f_xwidth,
        yheight = f_yheight,
        zdepth = f_zdepth,
        phi = f_phi,
        foilthick = f_foilthick,
        Bx = f_Bx,
        By = f_By,
        Bz = f_Bz,
        foil_in = f_foil_in,
        verbose = f_verbose;

    PolLambda_monitor px6 AT (0, 0, 0.16) RELATIVE f4 ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        nL = px_nL,
        restore_neutron = px_restore_neutron,
        filename = px_filename,
        mx = px_mx,
        Lmin = px_Lmin,
        Lmax = px_Lmax;

    PolAnalyser_ideal ana AT (0, 0, 4.4) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        mx = 1;

    PSD_monitor det AT (0, 0, 4.5) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        nx = det_nx,
        ny = det_ny,
        filename = det_filename,
        xwidth = det_xwidth,
        yheight = det_yheight;

    // Custom component trick using Arm
    Arm trick AT (0, 0, 4.4) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        EXTEND: {
            RESTORE_NEUTRON(INDEX_CURRENT_COMP-2, x, y, z, vx, vy, vz, t, sx, sy, sz, p);
        };

    PolAnalyser_ideal ana2 AT (0, 0, 4.4) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        mx = -1;

    PSD_monitor det2 AT (0, 0, 4.5) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE
        nx = det_nx,
        ny = det_ny,
        filename = det_filename,
        xwidth = det_xwidth,
        yheight = det_yheight;

    // Run the instrument
    DEFINE/INSTRUMENT
    run {
        // Set simulation parameters
        set_seed(123456); // Fixed seed for reproducibility
        set_ncount(1e6); // 1 million neutrons for reasonable statistics

        // Run the instrument
        run_instrument();
    }

    // Output results
    output {
        // Get results for each monitor
        real px1_intensity, px1_rel_err, px1_events;
        px1_intensity = get_monitor_intensity(px1, "I");
        px1_rel_err = get_monitor_rel_err(px1, "I");
        px1_events = get_monitor_events(px1);

        real px2_intensity, px2_rel_err, px2_events;
        px2_intensity = get_monitor_intensity(px2, "I");
        px2_rel_err = get_monitor_rel_err(px2, "I");
        px2_events = get_monitor_events(px2);

        real px3_intensity, px3_rel_err, px3_events;
        px3_intensity = get_monitor_intensity(px3, "I");
        px3_rel_err = get_monitor_rel_err(px3, "I");
        px3_events = get_monitor_events(px3);

        real px6_intensity, px6_rel_err, px6_events;
        px6_intensity = get_monitor_intensity(px6, "I");
        px6_rel_err = get_monitor_rel_err(px6, "I");
        px6_events = get_monitor_events(px6);

        real det_intensity, det_rel_err, det_events;
        det_intensity = get_monitor_intensity(det, "I");
        det_rel_err = get_monitor_rel_err(det, "I");
        det_events = get_monitor_events(det);

        real det2_intensity, det2_rel_err, det2_events;
        det2_intensity = get_monitor_intensity(det2, "I");
        det2_rel_err = get_monitor_rel_err(det2, "I");
        det2_events = get_monitor_events(det2);

        // Print results
        print("Integrated intensity on px1: %g ± %g (events: %g, ncount: %g, seed: %d)\n",
              px1_intensity, px1_rel_err * px1_intensity, px1_events, get_ncount(), get_seed());
        print("Integrated intensity on px2: %g ± %g (events: %g, ncount: %g, seed: %d)\n",
              px2_intensity, px2_rel_err * px2_intensity, px2_events, get_ncount(), get_seed());
        print("Integrated intensity on px3: %g ± %g (events: %g, ncount: %g, seed: %d)\n",
              px3_intensity, px3_rel_err * px3_intensity, px3_events, get_ncount(), get_seed());
        print("Integrated intensity on px6: %g ± %g (events: %g, ncount: %g, seed: %d)\n",
              px6_intensity, px6_rel_err * px6_intensity, px6_events, get_ncount(), get_seed());
        print("Integrated intensity on det: %g ± %g (events: %g, ncount: %g, seed: %d)\n",
              det_intensity, det_rel_err * det_intensity, det_events, get_ncount(), get_seed());
        print("Integrated intensity on det2: %g ± %g (events: %g, ncount: %g, seed: %d)\n",
              det2_intensity, det2_rel_err * det2_intensity, det2_events, get_ncount(), get_seed());
    }
}
